// Auto-generated: subsetted Noto Sans (Regular, Bold, Black), base64-encoded TTF.
// Contains Basic Latin + common punctuation + currency symbols ($ £ ¥ € ₹) so
// jsPDF can render all currencies this app supports. jsPDF's built-in "helvetica"
// font (Standard-14 WinAnsi) is missing glyphs for ₹, €, and ¥, which caused
// corrupted/overflowing characters in generated PDFs (e.g. INR invoices).
// The Black (900) weight is used by the Modern template for dramatic headings.
// Regenerate by re-running the subsetting steps against a fresh Noto Sans
// variable font (google/fonts repo, ofl/notosans) if additional glyphs are needed.

export const NOTO_SANS_REGULAR_BASE64 = "";

export const NOTO_SANS_BOLD_BASE64 = "";

export const NOTO_SANS_BLACK_BASE64 = "";


